def compute(vars):
    london_market_reserves = vars["v1"]
    total_net_reserves = vars["v2"]

    if total_net_reserves == 0:
        return None

    value = london_market_reserves / total_net_reserves

    return {
        "value": value,
        "trace": {
            "london_market_reserves": london_market_reserves,
            "total_net_reserves": total_net_reserves,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
